// Iterate the Shopify customer pagination chain.
// Uses the current page's pageInfo.endCursor to fetch the next page.
// Breaks early if a customer's updatedAt is older than the cursor.

const crypto = { randomUUID: () => Math.random().toString(36).substring(2) + Date.now().toString(36) };

const firstPage = $input.first().json;
const lastCursor = $('Read Sync Cursor').first().json.last_updated_at;
const accessToken = $('Fetch Shopify Token').first().json.access_token;
const shopUrl = 'https://YOUR_SHOPIFY_SHOP/admin/api/2026-10/graphql.json';

const allCustomers = [];
let page = firstPage;
let pageCount = 0;
let done = false;

while (!done) {
  const edges = page.data.customers.edges || [];
  pageCount++;

  for (const edge of edges) {
    const node = edge.node;
    const updatedAt = node.updatedAt;

    if (new Date(updatedAt) <= new Date(lastCursor)) {
      // Reached customers older than the cursor. Stop.
      done = true;
      break;
    }

    allCustomers.push(node);
  }

  const hasNextPage = page.data.customers.pageInfo.hasNextPage;
  if (!hasNextPage || done) {
    break;
  }

  const endCursor = page.data.customers.pageInfo.endCursor;

  // Fetch next page
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: shopUrl,
    headers: {
      'X-Shopify-Access-Token': accessToken,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      query: 'query FetchCustomers($cursor: String, $pageSize: Int!) { customers(first: $pageSize, after: $cursor, sortKey: UPDATED_AT, reverse: true) { edges { cursor node { id email firstName lastName numberOfOrders amountSpent { amount currencyCode } updatedAt } } pageInfo { hasNextPage endCursor } } }',
      variables: { cursor: endCursor, pageSize: 2 }
    }),
    json: true
  });

  page = response;
}

const runStartedAt = $('Read Sync Cursor').first().json.run_started_at;

return [{
  json: {
    customers: allCustomers,
    total_fetched: allCustomers.length,
    pages_fetched: pageCount,
    last_cursor_from_shopify: firstPage.data.customers.pageInfo.endCursor,
    run_started_at: runStartedAt
  }
}];

// Reshape the Shopify customer array into two output shapes:
//  - one summary item with skip counts and the highest updated_at
//  - one customer item per valid customer (skips those with no email)
//
// Downstream nodes filter on json.type.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];

  const customers = Array.isArray(item.json.customers) ? item.json.customers : [];
  const run_id = $('Read Sync Cursor').first().json.run_id;
  const last_updated_at = $('Read Sync Cursor').first().json.last_updated_at;

  let skipped_no_email = 0;
  let highest_updated_at = last_updated_at;

  for (const c of customers) {
    // Track the highest updatedAt across all fetched customers, including skipped ones.
    // The cursor advance uses this value; skip decisions do not affect it.
    if (c.updatedAt) {
      const cUpdated = new Date(c.updatedAt);
      if (cUpdated > new Date(highest_updated_at)) {
        highest_updated_at = c.updatedAt;
      }
    }

    // Skip no-email customers.
    // Shopify returns email: null for customers with no email.
    // Whitespace-only strings are defensively treated as missing.
    const rawEmail = c.email ? String(c.email).trim() : '';
    if (!rawEmail) {
      skipped_no_email++;
      continue;
    }

    const email = rawEmail.toLowerCase();

    // numberOfOrders is a string in the GraphQL response. Coerce to a number
    // and back to a string so "00" and "0" normalize the same way.
    const orderCountRaw = c.numberOfOrders !== undefined && c.numberOfOrders !== null
      ? Number(c.numberOfOrders)
      : 0;
    const orderCount = isNaN(orderCountRaw) ? 0 : orderCountRaw;

    // amountSpent is an object. Defensive against a missing field.
    const amountRaw = (c.amountSpent && c.amountSpent.amount) ? Number(c.amountSpent.amount) : 0;
    const amountSafe = isNaN(amountRaw) ? 0 : amountRaw;

    results.push({
      json: {
        type: 'customer',
        run_id: run_id,
        last_updated_at: last_updated_at,
        customer_updated_at: c.updatedAt || null,
        customer: {
          shopify_id: c.id || null,
          email: email,
          firstname: c.firstName || null,
          lastname: c.lastName || null,
          shopify_order_count: String(orderCount),
          shopify_total_spent: amountSafe.toFixed(2)
        }
      }
    });
  }

  // Emit the summary item last so downstream nodes can read it after processing customers.
  results.push({
    json: {
      type: 'summary',
      run_id: run_id,
      run_started_at: item.json.run_started_at || null,
      last_updated_at: last_updated_at,
      total_customers: customers.length,
      skipped_no_email: skipped_no_email,
      customers_mapped: customers.length - skipped_no_email,
      highest_updated_at: highest_updated_at
    }
  });
}

return results;

// Split the mapped customers into chunks of up to 100 for HubSpot's
// batch upsert endpoint. Carry the summary item through to the end so
// downstream nodes can read the run totals.

const CHUNK_SIZE = 100;

const input = $input.all();

// Separate customer items from the summary item
const customerItems = input.filter(i => i.json.type === 'customer');
const summaryItem = input.find(i => i.json.type === 'summary');

// Defensive: summary must exist. If it does not, fabricate a minimal one.
const summary = summaryItem ? summaryItem.json : {
  type: 'summary',
  run_id: null,
  last_updated_at: null,
  total_customers: customerItems.length,
  skipped_no_email: 0,
  customers_mapped: customerItems.length,
  highest_updated_at: null
};

// Build HubSpot batch upsert inputs from each customer item.
// Property names: firstname, lastname (no underscore).
// Custom properties: shopify_order_count, shopify_total_spent (Number type, string values).
const hubspotInputs = customerItems.map(i => {
  const c = i.json.customer;
  return {
    idProperty: 'email',
    id: c.email,
    properties: {
      email: c.email,
      firstname: c.firstname,
      lastname: c.lastname,
      shopify_order_count: c.shopify_order_count,
      shopify_total_spent: c.shopify_total_spent
    }
  };
});

// Chunk into groups of CHUNK_SIZE.
const chunks = [];
for (let i = 0; i < hubspotInputs.length; i += CHUNK_SIZE) {
  chunks.push({
    json: {
      type: 'chunk',
      chunk_index: Math.floor(i / CHUNK_SIZE),
      chunk_size: Math.min(CHUNK_SIZE, hubspotInputs.length - i),
      run_id: summary.run_id,
      last_updated_at: summary.last_updated_at,
      inputs: hubspotInputs.slice(i, i + CHUNK_SIZE)
    }
  });
}

// Emit chunk items only.
// The summary item is read downstream by Extract Summary from Map Customer Fields.

return chunks;

// Extract the summary item from Map Customer Fields.
// Map Customer Fields emits both customer items and one summary item.
// This node keeps only the summary so Write Run Summary gets a single item.

const items = $('Map Customer Fields').all();
const summary = items.find(i => i.json.type === 'summary');

if (!summary) {
  throw new Error('Summary item not found in Map Customer Fields output');
}

// Derive chunks_created from customers_mapped.
// HubSpot batch upserts accept up to 100 inputs per call.
// This avoids a cross-sibling reference to Chunk for HubSpot.
const chunksCreated = Math.ceil(summary.json.customers_mapped / 100);

return [{
  json: Object.assign({}, summary.json, {
    type: 'summary',
    chunks_created: chunksCreated
  })
}];
